require 'config.php'; require_login();
$user=current_user(); $role=$user['role'];
$counts=array_fill_keys(['Pending Admin Review','Pending Secretary Approval','Approved','Assigned','Dispatched','Returned','Rejected'],0);
if ($role==='requester') { $q=$conn->prepare('SELECT status,COUNT(*) c FROM reservations WHERE requester_id=? GROUP BY status'); $q->bind_param('i',$user['id']); }
else { $q=$conn->prepare('SELECT status,COUNT(*) c FROM reservations GROUP BY status'); }
$q->execute(); foreach ($q->get_result() as $row) { if (isset($counts[$row['status']])) $counts[$row['status']]=(int)$row['c']; }
if ($role==='requester') {
 $q=$conn->prepare('SELECT COUNT(*) c FROM reservations WHERE requester_id=?'); $q->bind_param('i',$user['id']); $q->execute(); $total=(int)$q->get_result()->fetch_assoc()['c'];
 $approvedStmt=$conn->prepare("SELECT id,reference_no,destination,departure_at,status FROM reservations WHERE requester_id=? AND status IN ('Approved','Assigned','Dispatched','Returned') ORDER BY created_at DESC LIMIT 5"); $approvedStmt->bind_param('i',$user['id']); $approvedStmt->execute(); $approvedRows=$approvedStmt->get_result();
 $stmt=$conn->prepare('SELECT r.*,v.vehicle_name,d.full_name driver_name FROM reservations r LEFT JOIN vehicles v ON r.vehicle_id=v.id LEFT JOIN drivers d ON r.driver_id=d.id WHERE r.requester_id=? ORDER BY r.created_at DESC LIMIT 8'); $stmt->bind_param('i',$user['id']);
} else { $total=(int)$conn->query('SELECT COUNT(*) c FROM reservations')->fetch_assoc()['c']; $stmt=$conn->prepare('SELECT r.*,u.full_name requester_name,v.vehicle_name,d.full_name driver_name FROM reservations r JOIN users u ON r.requester_id=u.id LEFT JOIN vehicles v ON r.vehicle_id=v.id LEFT JOIN drivers d ON r.driver_id=d.id ORDER BY r.created_at DESC LIMIT 8'); }
$stmt->execute(); $rows=$stmt->get_result();
$roleLabels=['admin'=>'Administrator','secretary'=>'Secretary','gso'=>'General Services Office','requester'=>'Requester'];
?>
